// Write a program that attaches to a virtual Layer-2 interface, waits in a loop,
// and prints out the length and raw bytes of any incoming Ethernet frame generated by the host OS.

#include<stdio.h>
#include<string.h>
#include<fcntl.h>
#include<unistd.h>
#include<sys/ioctl.h>
#include<sys/socket.h>
#include<linux/if_tun.h>
#include<net/if.h>
#include<arpa/inet.h>
#include <stdint.h>

// Configured details of YOUR device
const uint8_t MY_MAC[6] = {0x00, 0x0C, 0x29, 0xAB, 0xCD, 0xEF}; // Replace with your actual MAC
const uint8_t MY_IP[4]  = {192, 168, 42, 2};                     // Replace with your actual IP

#pragma pack(push, 1) // Prevents the compiler from padding the structure
struct eth_header {
    uint8_t  dest_mac[6];  // Destination MAC address
    uint8_t  src_mac[6];   // Source MAC address
    uint16_t ethertype;    // Type/Length field (e.g., 0x0800 for IPv4)
};
#pragma pack(pop)

// Define a minimal IPv4 Header to find the protocol field
#pragma pack(push, 1) // Prevents the compiler from padding the structure
struct ip_header {
    uint8_t  version_ihl;      // Version and Internet Header Length
    uint8_t  tos;              // Type of Service
    uint16_t total_length;
    uint16_t identification;
    uint16_t flags_fragment;
    uint8_t  ttl;              // Time to Live
    uint8_t  protocol;         // <--- THIS TELLS US IF IT'S ICMP/TCP/UDP
    uint16_t checksum;
    uint32_t src_ip;
    uint32_t dest_ip;
};
#pragma pack(pop)

// Define a minimal ARP header to find the target IP address
#pragma pack(push, 1)
struct arp_header {
    uint16_t htype;    // Hardware Type (1 for Ethernet)
    uint16_t ptype;    // Protocol Type (0x0800 for IPv4)
    uint8_t  hlen;     // Hardware Address Length (6 for MAC)
    uint8_t  plen;     // Protocol Address Length (4 for IP)
    uint16_t opcode;   // Operation (1 for Request, 2 for Reply)

    uint8_t  sender_mac[6]; // MAC of the device sending this request
    uint8_t  sender_ip[4];  // IP of the device sending this request
    uint8_t  target_mac[6]; // Target MAC (set to 00:00:00:00:00:00 in requests)
    uint8_t  target_ip[4];  // <--- THIS IS THE IP BEING REQUESTED!
};
#pragma pack(pop)

void send_arp_reply(int tap_fd, unsigned char *buffer) {
    // Prepare the pointers for the outgoing transmit buffer
    struct eth_header *rx_eth = (struct eth_header *)buffer;
    struct arp_header *rx_arp = (struct arp_header *)(buffer + 14);

    // 2. SAVE the critical incoming details into local variables
    //    BEFORE we start overwriting the buffer!
    uint8_t remote_mac[6];
    uint8_t remote_ip[4];
    memcpy(remote_mac, rx_arp->sender_mac, 6);
    memcpy(remote_ip, rx_arp->sender_ip, 4);

    // 3. Set up pointers for creating the outgoing response
    struct eth_header *tx_eth = (struct eth_header *)buffer;
    struct arp_header *tx_arp = (struct arp_header *)(buffer + sizeof(struct eth_header));

    // --- CONSTRUCT ETHERNET HEADER ---
    // Target MAC becomes the destination of the Ethernet frame
    memcpy(tx_eth->dest_mac, remote_mac, 6);

    // Your MAC becomes the source of the Ethernet frame
    memcpy(tx_eth->src_mac, MY_MAC, 6);
    tx_eth->ethertype = htons(0x0806); // ARP Protocol

    // --- CONSTRUCT ARP HEADER ---
    tx_arp->htype = htons(1); // Ethernet
    tx_arp->ptype = htons(0x0800); // Protocol
    tx_arp->hlen = 6;
    tx_arp->plen = 4;
    tx_arp->opcode = htons(2); // 2 = ARP reply

    // Sender fields
    memcpy(tx_arp->sender_mac, MY_MAC, 6);
    memcpy(tx_arp->sender_ip, MY_IP, 4);

    // Dest fields
    memcpy(tx_arp->target_mac, remote_mac, 6);
    memcpy(tx_arp->target_ip, remote_ip, 4);

    // Total size of an Ethernet + ARP packet is 14 + 28 = 42 bytes
    int tx_len = sizeof(struct eth_header) + sizeof(struct arp_header);

    int l = write(tap_fd, buffer, tx_len);
    if(l != tx_len) {
        printf("something went wrong!! complete arp reply is not sent");
    }

}

void parse_arp_request(int tap_fd, unsigned char *buffer) {
    // 1. Jump past the 14-byte Ethernet header to point to the ARP header
    struct arp_header *arp = (struct arp_header *)(buffer + 14);

    // 2. Always convert the network byte-order integer (Big-Endian) to Host order
    uint16_t op = ntohs(arp->opcode);

    // 3. Check if it is an ARP Request (Opcode = 1)
    if (op == 1) {
        printf("--- ARP Request Detected ---\n");
        // Print the Sender's info (Who is asking)
        printf("Sender IP: %d.%d.%d.%d\n",
               arp->sender_ip[0], arp->sender_ip[1],
               arp->sender_ip[2], arp->sender_ip[3]);

        // Print the Target IP (The IP being looked up)
        printf("Looking for IP: %d.%d.%d.%d\n",
               arp->target_ip[0], arp->target_ip[1],
               arp->target_ip[2], arp->target_ip[3]);

        printf("Question: \"Who has %d.%d.%d.%d? Tell %d.%d.%d.%d\"\n",
               arp->target_ip[0], arp->target_ip[1], arp->target_ip[2], arp->target_ip[3],
               arp->sender_ip[0], arp->sender_ip[1], arp->sender_ip[2], arp->sender_ip[3]);

        if (arp->target_ip[0] == 192 && arp->target_ip[1] == 168 && arp->target_ip[2] == 42 && arp->target_ip[3] == 2) {
            // better way to compare the IP.
            // if (memcmp(arp->target_ip, MY_IP, 4) != 0) {
            //    return; // Someone else's IP is being requested, ignore it
            // }

            printf("ARP Request matched my IP! Constructing reply...\n");
            // Send the arp reply and poison the linux system arp cache
            send_arp_reply(tap_fd, buffer);
        }
    }

}

void parse_ethernet_header(int tap_fd, int frame_len, unsigned char *buffer) {
    // The buffer now holds raw Layer 2 data!
    printf("\n--- Received a Layer 2 Frame (%d bytes) ---\n", frame_len);

    // Parsing the Layer 2 Ethernet Header:
    // Bytes 0-5:  Destination MAC Address
    // Bytes 6-11: Source MAC Address
    // Bytes 12-13: EtherType (e.g., 0x0800 for IPv4, 0x0806 for ARP)

    // Cast the raw byte buffer to the Ethernet structure
    struct eth_header *eth = (struct eth_header *)buffer;

    // Print MAC addresses
    printf("Destination MAC: %02x:%02x:%02x:%02x:%02x:%02x\n",
           eth->dest_mac[0], eth->dest_mac[1], eth->dest_mac[2],
           eth->dest_mac[3], eth->dest_mac[4], eth->dest_mac[5]);

    printf("Source MAC:      %02x:%02x:%02x:%02x:%02x:%02x\n",
           eth->src_mac[0], eth->src_mac[1], eth->src_mac[2],
           eth->src_mac[3], eth->src_mac[4], eth->src_mac[5]);

    // Convert network byte order (big-endian) to host byte order
    printf("EtherType before ntohs:       0x%04x\n", eth->ethertype);
    uint16_t type = ntohs(eth->ethertype);
    printf("EtherType after ntohs:       0x%04x\n", type);

    if (type == (uint16_t)0x0806) {
        printf("This is ARP request\n");
        parse_arp_request(tap_fd, buffer);
    }
    else if(type == (uint16_t)0x0800) {
        printf("IPv4 Packet... Checking inner protocol...\n");

        struct ip_header *ip = (struct ip_header *)(buffer + 14);
        printf("  IP Protocol Byte: %d -> ", ip->protocol);

        switch(ip->protocol) {
        case 1:
            printf("Protocol Detected: ICMP (Ping Request/Reply)\n");
            // TODO: prepare to send the ICMP ping reply
            break;
        case 6:
            printf("Protocol Detected: TCP\n");
            break;
        case 17:
            printf("Protocol Detected: UDP\n");
            break;
        default:
            printf("Protocol Detected: Other IP Protocol\n");
            break;
        }

    }
    else if (type == 0x86DD) {
        printf("Protocol Detected: IPv6 Packet\n");
    }
    else {
        printf("Protocol Detected: Unknown/Other\n");
    }

}


int main() {
    struct ifreq ifr;
    int sock_fd;

    // 1. open the virtual device gateway and spawn the TAP interface
    int tap_fd = open("/dev/net/tun", O_RDWR);
    if (tap_fd < 0) {
        perror("Opening /dev/net/tun failed");
        return 1;
    }

    memset(&ifr, 0, sizeof(ifr));
    ifr.ifr_flags = IFF_TAP | IFF_NO_PI;
    strncpy(ifr.ifr_name, "tap0", IFNAMSIZ);
    if (ioctl(tap_fd, TUNSETIFF, (void *)&ifr) < 0) {
        perror("ioctl(TUNSETIFF) failed");
        close(tap_fd);
        return 1;
    }
    printf("Successfully spawned: %s\n", ifr.ifr_name);

    // 2. Open a standard socket to apply routing/IP configurations
    // (You cannot use the tap_fd itself for SIOCSIFADDR; you need a network socket)
    sock_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock_fd < 0) {
        perror("Socket creation failed");
        close(tap_fd);
        return 1;
    }

    // 3. PROGRAMMATICALLY ADD IP ADDRESS (192.168.42.1)
    struct sockaddr_in *addr = (struct sockaddr_in *)&ifr.ifr_addr;
    memset(addr, 0, sizeof(struct sockaddr_in));
    addr->sin_family = AF_INET;
    // Convert text IP string to binary form
    inet_pton(AF_INET, "192.168.42.1", &addr->sin_addr);

    if (ioctl(sock_fd, SIOCSIFADDR, &ifr) < 0) {
        perror("ioctl(SIOCSIFADDR) failed");
        close(sock_fd);
        close(tap_fd);
        return 1;
    }
    printf("Successfully assigned IP 192.168.42.1 to %s\n", ifr.ifr_name);

    // Set Subnet Mask: 255.255.255.0 (/24)
    struct sockaddr_in *netmask = (struct sockaddr_in *)&ifr.ifr_netmask;
    memset(netmask, 0, sizeof(struct sockaddr_in));
    netmask->sin_family = AF_INET;
    inet_pton(AF_INET, "255.255.255.0", &netmask->sin_addr);
    if (ioctl(sock_fd, SIOCSIFNETMASK, &ifr) < 0) {
        perror("ioctl(SIOCSIFNETMASK) failed");
    }

    // 4. PROGRAMMATICALLY SET LINK UP & RUNNING
    // First, fetch the current flags to avoid overwriting default internal flags
    if (ioctl(sock_fd, SIOCGIFFLAGS, &ifr) < 0) {
        perror("ioctl(SIOCGIFFLAGS) failed");
    } else {
        // Bitwise OR to turn on the UP and RUNNING switches
        ifr.ifr_flags |= (IFF_UP | IFF_RUNNING);

        if (ioctl(sock_fd, SIOCSIFFLAGS, &ifr) < 0) {
            perror("ioctl(SIOCSIFFLAGS) failed");
        } else {
            printf("Interface %s is now UP and RUNNING!\n", ifr.ifr_name);
        }
    }

    unsigned char buffer[2000]; // Buffer large enough for a standard Ethernet frame (MTU 1500)

    printf("Listening for Layer 2 Ethernet frames... Press Ctrl+C to stop.\n");

    while (1) {
        int frame_len = read(tap_fd, buffer, sizeof(buffer));
        if (frame_len < 0) {
            perror("Read error");
            break;
        }

        parse_ethernet_header(tap_fd, frame_len, buffer);


    }

    close(sock_fd);
    close(tap_fd);
    return 0;
}


